targets.expr:
100 *
sum by (namespace, pod) (
  rate(container_cpu_usage_seconds_total{
    job="kubernetes-cadvisor",
  }[5m])
)
/
clamp_min(
  sum by (namespace, pod) (
    kube_pod_container_resource_requests{
      resource="cpu",
      unit="core"
    }
  ),
  0.001
)

100 *
sum by (namespace, pod) (
  rate(container_cpu_cfs_throttled_periods_total{
    job="kubernetes-cadvisor",
  }[5m])
)
/
clamp_min(
  sum by (namespace, pod) (
    rate(container_cpu_cfs_periods_total{
      job="kubernetes-cadvisor",
    }[5m])
  ),
  0.001
)
